signal steps:steps_t(0 to G_CAPACITY-1);signal offsets:offsets_t(0 to G_CAPACITY-1);
signal fwd,rev:delays_t(0 to G_CAPACITY-1);
signal raw:std_logic_vector(63 downto 0);
signal times,corrections,delays,theta,ages,indices:words64_t(0 to G_CAPACITY-1);
signal accepted,rejected,deferred,skipped,backsteps:words32_t(0 to G_CAPACITY-1);
signal dropped:words32_t(0 to G_CAPACITY-1);
signal running,locked,holdover,errors,pulses:std_logic_vector(0 to G_CAPACITY-1);
signal al,ar:audits_t(0 to G_CAPACITY-1);
signal obs_active:unsigned(15 downto 0);signal obs_valid,obs_error,ref_owner:std_logic;

entity ptp_observer is
  generic(G_CAPACITY:positive:=20);
  port(clk_i,rst_i:in std_logic;first_i:in natural;count_i:in natural;
    pulses_i:in std_logic_vector(0 to G_CAPACITY-1);
    shadow_i:in unsigned(15 downto 0);apply_i,enable_i:in std_logic;
    ref_owner_i:in std_logic;ref_o,obs_o:out std_logic;
    active_o:out unsigned(15 downto 0);valid_o,error_o:out std_logic);

process(clk_i)
  variable requested:natural;
begin if rising_edge(clk_i) then
  prev_apply<=apply_i;
  if rst_i='1' then
    selected<=0;target<=0;active_id<=to_unsigned(first_i,16);valid<='0';error<='0';
    pending<='0';waiting<='0';enabled<='0';prev_apply<='0';pin<='0';ref_o<='0';
  else
    ref_o<=pulses_i(0) and ref_owner_i;
    pin<='0';
    if enabled='1' then pin<=pulses_i(selected);end if;
    if to_integer(active_id)<first_i or to_integer(active_id)>=first_i+count_i then
      valid<='0';enabled<='0';pending<='0';waiting<='0';
    end if;
    if apply_i='1' and prev_apply='0' then
      requested:=to_integer(shadow_i);
      if pending='1' or waiting='1' or requested<first_i or requested>=first_i+count_i then error<='1';
      else target<=requested-first_i;target_enabled<=enable_i;pending<='1';valid<='0';error<='0';end if;
    end if;
    -- Finish the old high interval before touching the mux. Wait for a low
    -- level on the target, so joining a pulse cannot create a spurious edge.
    if pending='1' and pin='0' and (enabled='0' or pulses_i(selected)='0') then
      enabled<='0';selected<=target;active_id<=to_unsigned(first_i+target,16);
      pending<='0';waiting<='1';pin<='0';
    elsif waiting='1' and pulses_i(selected)='0' then
      waiting<='0';enabled<=target_enabled;valid<=target_enabled;

first<=first_node(nodes,board);count<=population(nodes,board);
config_id_o<=active(4);ref_owner<='1' when board=0 and configured='1' else '0';
obs_status_o<=(63 downto 18=>'0')&obs_error&obs_valid&std_logic_vector(obs_active);

pulse_o<='1' when width>0 else '0';index_o<=idx;
skipped_o<=skipped;backsteps_o<=backsteps;
process(clk_i)
  variable period_q:unsigned(63 downto 0);
begin if rising_edge(clk_i) then
  period_q:=shift_left(to_unsigned(period_i,64),16);
  if rst_i='1' then
    next_epoch<=epoch_i;idx<=(others=>'0');width<=0;enabled<='0';catching_up<='0';
    skipped<=(others=>'0');backsteps<=(others=>'0');previous<=unsigned(time_i);
  else
    previous<=unsigned(time_i);
    if width>0 then width<=width-1;end if;
    if enable_i='0' then enabled<='0';width<=0;next_epoch<=epoch_i;idx<=(others=>'0');
    elsif enabled='0' then enabled<='1';next_epoch<=epoch_i;idx<=(others=>'0');catching_up<='0';
    else
      if unsigned(time_i)<previous then backsteps<=backsteps+1;end if;
      if unsigned(time_i)>=next_epoch then
        -- Advance at most one index per tick. Do not emit catch-up pulses.
        if unsigned(time_i)-next_epoch>=period_q then
          skipped<=skipped+1;catching_up<='1';
        elsif catching_up='1' or width>0 then
          skipped<=skipped+1;catching_up<='0';
        else width<=width_i;end if;
        next_epoch<=next_epoch+period_q;idx<=idx+1;

id_cfg<=config_id_i when G_RUNTIME_CONFIG else G_NODE_ID;
assert G_NODE_ID<G_NODES severity failure;
start_edge<=start_i and not previous_start;
assert G_WINDOW_CYCLES<G_PERIOD_CYCLES severity failure;
logical<=std_logic_vector(signed(logical_accum(79 downto 16))+correction);
raw_counter_o<=std_logic_vector(raw);logical_time_o<=logical;offset_o<=std_logic_vector(correction);path_delay_o<=std_logic_vector(path);cycle_id_o<=std_logic_vector(cycle);running_o<=run;sync_locked_o<=locked;sync_window_miss_o<=std_logic_vector(misses);error_o<=sticky_error;

